model:
rachana: 1
sutra: repo-curve
version: 1
description: 
match: { kind: repo-curve, priority: 10 }
title: { pill: "Market data · Repo curve", id: "$.CURVE_ID" }
strip:
  - { label: "Currency", bind: "$.CURRENCY" }
  - { label: "Collateral", bind: "$.COLLATERAL" }
  - { label: "O/N", bind: "$.OVERNIGHT", fmt: "pct4", emphasis: true }
  - { label: "As of", bind: "$.AS_OF", fmt: "date" }
panels:
  - id: curve
    kind: line
    title: "Repo rates (%)"
    key: "F2"
    phone: { tier: "glance", from: "fragment" }
    rows: "$.POINTS"
    x: "TENOR"
    y: "RATE"
    fmt: "price2"
  - id: points
    kind: table
    title: "Terms"
    rows: "$.POINTS"
    columns:
      - { label: "Term", bind: "@.TENOR" }
      - { label: "Rate (%)", bind: "@.RATE", fmt: "price2" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F8: "impact", F9: "raw" }
